import React, { useState, useContext } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { OrderContext } from "./OrderContext";
import backgroundImage from "../Img/order8.jpg";

const AddOrder = () => {
  const [orderData, setOrderData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phoneNumber: "",
    address: "",
    city: "",
    orderId: "",
    specialInstructions: "",
    pickupTime: "",
    orderStatus: "",
  });

  const [errors, setErrors] = useState({});
  const { setOrdersChanged } = useContext(OrderContext);
  const navigate = useNavigate();

  const validateForm = () => {
    let newErrors = {};

    if (!orderData.firstName.trim()) {
      newErrors.firstName = "First Name is required.";
    } else if (!/^[A-Za-z]+$/.test(orderData.firstName)) {
      newErrors.firstName = "First Name should only contain letters.";
    }

    if (!orderData.lastName.trim()) {
      newErrors.lastName = "Last Name is required.";
    } else if (!/^[A-Za-z]+$/.test(orderData.lastName)) {
      newErrors.lastName = "Last Name should only contain letters.";
    }

    if (!orderData.email.trim()) {
      newErrors.email = "Email is required.";
    } else if (!/\S+@\S+\.\S+/.test(orderData.email)) {
      newErrors.email = "Enter a valid email address.";
    }

    if (!orderData.phoneNumber.trim()) {
      newErrors.phoneNumber = "Phone Number is required.";
    } else if (!/^\d{10}$/.test(orderData.phoneNumber)) {
      newErrors.phoneNumber = "Phone Number must be exactly 10 digits and contain no letters or special characters.";
    }
    if (!orderData.address.trim()) newErrors.address = "Address is required.";
    if (!orderData.city.trim()) newErrors.city = "City is required.";
    if (!orderData.orderId.trim()) newErrors.orderId = "Order ID is required.";

    if (!orderData.pickupTime.trim()) {
      newErrors.pickupTime = "Pickup Time is required.";
    } else {
      const currentTime = new Date();
      const selectedTime = new Date(orderData.pickupTime);
      if (selectedTime <= currentTime) {
        newErrors.pickupTime = "Pickup Time must be in the future.";
      }
    }

    if (!orderData.orderStatus.trim()) newErrors.orderStatus = "Order Status is required.";

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    let newErrors = { ...errors };
    
    setOrderData({ ...orderData, [name]: value });
    
    if (name === "firstName" || name === "lastName") {
      if (value.trim() !== "" && !/^[A-Za-z]+$/.test(value)) {
        if (/\d/.test(value)) {
          newErrors[name] = `${name === "firstName" ? "First Name" : "Last Name"} cannot contain numbers.`;
        } else if (/[^A-Za-z]/.test(value)) {
          newErrors[name] = `${name === "firstName" ? "First Name" : "Last Name"} cannot contain special characters.`;
        }
      } else {
        delete newErrors[name];
      }
    }
    
    if (name === "email") {
      if (value.trim() !== "") {
        if (!/@/.test(value)) {
          newErrors.email = "Email must contain @ symbol.";
        } else if (!/\S+@\S+\.\S+/.test(value)) {
          newErrors.email = "Email format is invalid. Please use format: example@domain.com";
        } else {
          delete newErrors.email;
        }
      } else {
        delete newErrors.email;
      }
    }
    
    if (name === "phoneNumber") {
      if (value.trim() !== "") {
        if (!/^\d*$/.test(value)) {
          newErrors.phoneNumber = "Phone Number must only contain digits.";
        } else if (value.length !== 10 && value.length > 0) {
          newErrors.phoneNumber = `Phone Number must be 10 digits. Currently: ${value.length} digits.`;
        } else {
          delete newErrors.phoneNumber;
        }
      } else {
        delete newErrors.phoneNumber;
      }
    }
    
    if (name === "pickupTime" && value.trim() !== "") {
      const currentTime = new Date();
      const selectedTime = new Date(value);
      if (selectedTime <= currentTime) {
        newErrors.pickupTime = "Pickup Time must be in the future.";
      } else {
        delete newErrors.pickupTime;
      }
    }
    
    setErrors(newErrors);
  };

  const sendData = (e) => {
    e.preventDefault();

    if (!validateForm()) return;

    axios
      .post("http://localhost:5000/orders/", orderData)
      .then(() => {
        alert("Order Added");
        setOrderData({
          firstName: "",
          lastName: "",
          email: "",
          phoneNumber: "",
          address: "",
          city: "",
          orderId: "",
          specialInstructions: "",
          pickupTime: "",
          orderStatus: "",
        });

        setOrdersChanged((prev) => !prev);
        navigate("/all-orders");
      })
      .catch((err) => {
        alert(err);
      });
  };

  const handleBackToHome = () => {
    navigate("/");
  };

  return (
    <div 
      className="flex justify-center items-center min-h-[130vh] bg-gray-100 bg-cover bg-no-repeat bg-blend-multiply"
      style={{ backgroundImage: `url(${backgroundImage})` }}
    >
      <div className="bg-white/70 p-5 rounded-lg shadow w-full max-w-[700px] box-border">
        <h1 className="text-[#8B0000] font-bold text-center mb-5 text-2xl">
          Add Order
        </h1>
        
        <form onSubmit={sendData} className="w-full space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label htmlFor="firstName" className="block font-medium text-gray-700 mb-1">
                First Name
              </label>
              <input
                type="text"
                id="firstName"
                name="firstName"
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#b30000]"
                placeholder="Enter First Name"
                value={orderData.firstName}
                onChange={handleChange}
              />
              {errors.firstName && <p className="mt-1 text-sm text-red-600">{errors.firstName}</p>}
            </div>

            <div>
              <label htmlFor="lastName" className="block font-medium text-gray-700 mb-1">
                Last Name
              </label>
              <input
                type="text"
                id="lastName"
                name="lastName"
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#b30000]"
                placeholder="Enter Last Name"
                value={orderData.lastName}
                onChange={handleChange}
              />
              {errors.lastName && <p className="mt-1 text-sm text-red-600">{errors.lastName}</p>}
            </div>

            <div>
              <label htmlFor="email" className="block font-medium text-gray-700 mb-1">
                Email
              </label>
              <input
                type="email"
                id="email"
                name="email"
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#b30000]"
                placeholder="Enter Email"
                value={orderData.email}
                onChange={handleChange}
              />
              {errors.email && <p className="mt-1 text-sm text-red-600">{errors.email}</p>}
            </div>

            <div>
              <label htmlFor="phoneNumber" className="block font-medium text-gray-700 mb-1">
                Phone Number
              </label>
              <input
                type="text"
                id="phoneNumber"
                name="phoneNumber"
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#b30000]"
                placeholder="Enter Phone Number"
                value={orderData.phoneNumber}
                onChange={handleChange}
              />
              {errors.phoneNumber && <p className="mt-1 text-sm text-red-600">{errors.phoneNumber}</p>}
            </div>

            <div className="md:col-span-2">
              <label htmlFor="address" className="block font-medium text-gray-700 mb-1">
                Address
              </label>
              <input
                type="text"
                id="address"
                name="address"
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#b30000]"
                placeholder="Enter Address"
                value={orderData.address}
                onChange={handleChange}
              />
              {errors.address && <p className="mt-1 text-sm text-red-600">{errors.address}</p>}
            </div>

            <div>
              <label htmlFor="city" className="block font-medium text-gray-700 mb-1">
                City
              </label>
              <input
                type="text"
                id="city"
                name="city"
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#b30000]"
                placeholder="Enter City"
                value={orderData.city}
                onChange={handleChange}
              />
              {errors.city && <p className="mt-1 text-sm text-red-600">{errors.city}</p>}
            </div>

            <div>
              <label htmlFor="orderId" className="block font-medium text-gray-700 mb-1">
                Order ID
              </label>
              <input
                type="text"
                id="orderId"
                name="orderId"
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#b30000]"
                placeholder="Enter Order ID"
                value={orderData.orderId}
                onChange={handleChange}
              />
              {errors.orderId && <p className="mt-1 text-sm text-red-600">{errors.orderId}</p>}
            </div>

            <div className="md:col-span-2">
              <label htmlFor="specialInstructions" className="block font-medium text-gray-700 mb-1">
                Special Instructions
              </label>
              <input
                type="text"
                id="specialInstructions"
                name="specialInstructions"
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#b30000]"
                placeholder="Enter Special Instructions"
                value={orderData.specialInstructions}
                onChange={handleChange}
              />
            </div>

            <div>
              <label htmlFor="pickupTime" className="block font-medium text-gray-700 mb-1">
                Pickup Time
              </label>
              <input
                type="datetime-local"
                id="pickupTime"
                name="pickupTime"
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#b30000]"
                value={orderData.pickupTime}
                onChange={handleChange}
              />
              {errors.pickupTime && <p className="mt-1 text-sm text-red-600">{errors.pickupTime}</p>}
            </div>

            <div>
              <label htmlFor="orderStatus" className="block font-medium text-gray-700 mb-1">
                Order Status
              </label>
              <input
                type="text"
                id="orderStatus"
                name="orderStatus"
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#b30000]"
                placeholder="Enter Order Status"
                value={orderData.orderStatus}
                onChange={handleChange}
              />
              {errors.orderStatus && <p className="mt-1 text-sm text-red-600">{errors.orderStatus}</p>}
            </div>
          </div>

          <div className="flex justify-between items-center mt-6">
            <button
              type="submit"
              className="bg-[#b30000] hover:bg-[#8B0000] text-white font-medium py-2 px-6 rounded-md transition duration-300"
            >
              Submit Order
            </button>
            
            <button
              type="button"
              onClick={handleBackToHome}
              className="bg-gray-500 hover:bg-gray-600 text-white font-medium py-2 px-6 rounded-md transition duration-300"
            >
              Back to Home
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AddOrder;
